const otp = String(Math.floor(100000 + Math.random() * 900000));
// store a hash of otp against the login attempt, with an expiry

const res = await fetch('https://api.startmessaging.com/otp/send', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'X-API-Key': process.env.SM_API_KEY,
  },
  body: JSON.stringify({
    phoneNumber: '+919876543210',
    templateId: 'YOUR_TEMPLATE_ID',
    variables: { otp, appName: 'YourApp' },
  }),
});

const { data } = await res.json();
console.log(data.messageId, data.status); // queued
